WITH row_rank_1 AS (
    SELECT DISTINCT ON (rr.HK_LISTING) rr.HK_LISTING, rr.listing_id, rr.LOAD_DATETIME, rr.RECORD_SOURCE
    FROM "krisha_dwh"."marts_dv"."stg_dv_listings" AS rr
    WHERE rr.HK_LISTING IS NOT NULL
    ORDER BY rr.HK_LISTING, rr.LOAD_DATETIME
),

records_to_insert AS (
    SELECT a.HK_LISTING, a.listing_id, a.LOAD_DATETIME, a.RECORD_SOURCE
    FROM row_rank_1 AS a
    LEFT JOIN "krisha_dwh"."marts_dv"."hub_listing" AS d
    ON a.HK_LISTING = d.HK_LISTING
    WHERE d.HK_LISTING IS NULL
)

SELECT * FROM records_to_insert